  function renderStock(){var host=document.getElementById('inventory-stock'),rows=state.snapshot.filter(function(x){return !state.location||x.location_id===state.location;}),search=(document.getElementById('inventory-search').value||'').toLowerCase();if(state.stockFilter==='attention')rows=rows.filter(function(x){return x.below_minimum||(x.days_to_expiry!=null&&Number(x.days_to_expiry)<=30&&Number(x.on_hand)>0);});if(state.stockFilter==='low')rows=rows.filter(function(x){return x.below_minimum;});if(state.stockFilter==='expiry')rows=rows.filter(function(x){return x.days_to_expiry!=null&&Number(x.days_to_expiry)<=30&&Number(x.on_hand)>0;});if(search)rows=rows.filter(function(x){return (x.item_name+' '+x.sku+' '+x.category).toLowerCase().includes(search);});document.querySelectorAll('[data-stock-filter]').forEach(function(b){b.setAttribute('aria-selected',String(b.dataset.stockFilter===state.stockFilter));});host.innerHTML=rows.length?'<div class="inventory-table"><div class="inventory-row inventory-row-head"><span>Insumo</span><span>Ubicación</span><span>Existencia</span><span>Próxima caducidad</span><span>Control</span></div>'+rows.map(function(x){var expired=x.days_to_expiry!=null&&Number(x.days_to_expiry)<0,tone=expired?'expired':x.below_minimum?'low':x.days_to_expiry!=null&&x.days_to_expiry<=30?'expiry':'ok',suggested=suggestedPurchase(x);return '<article class="inventory-row" data-tone="'+tone+'"><div><strong>'+esc(x.item_name)+'</strong><small>'+esc(x.sku)+' · '+esc(x.category)+(x.requires_patient_trace?' · Trazabilidad por paciente':'')+'</small></div><span>'+esc(x.location_name)+'</span><div><strong>'+fmt(x.on_hand)+' '+esc(x.unit)+'</strong><small>'+(suggested?'Sugerido pedir '+fmt(suggested)+' · ':'')+'Mínimo '+fmt(x.minimum_quantity)+'</small></div><span>'+(x.nearest_expiry?date(x.nearest_expiry)+(expired?' · Caducado':x.days_to_expiry<=30?' · '+x.days_to_expiry+' días':''):'Sin caducidad')+'</span><div><span class="inventory-badge" data-tone="'+tone+'">'+(expired?'No utilizar':x.below_minimum?'Reponer':tone==='expiry'?'Por caducar':'Disponible')+'</span>'+(state.canManage?'<button data-reorder="'+x.item_id+'" data-location="'+x.location_id+'">Mínimos</button>':'')+'</div></article>';}).join('')+'</div>':'<div class="inventory-empty"><strong>Sin resultados en este filtro</strong><p>Prueba otra ubicación, estado o término de búsqueda.</p></div>';host.querySelectorAll('[data-reorder]').forEach(function(b){b.onclick=function(){openReorder(b.dataset.reorder,b.dataset.location);};});}
  function renderMovements(){var h=document.getElementById('inventory-movements'),rows=state.movements.slice(0,100);h.innerHTML=rows.length?rows.map(function(m){var lines=state.movementLines.filter(function(l){return l.movement_id===m.id;}),src=by(state.locations,m.source_location_id),dst=by(state.locations,m.destination_location_id),reversed=state.movements.some(function(x){return x.reversal_of===m.id;});return '<article class="inventory-movement"><div class="inventory-movement-icon" data-type="'+m.movement_type+'">'+(m.movement_type==='transfer'?'↔':m.destination_location_id?'+':'−')+'</div><div><span>'+esc(TYPES[m.movement_type]||m.movement_type)+'</span><strong>'+lines.map(function(l){var i=by(state.items,l.item_id);return fmt(l.quantity)+' '+esc(i?i.unit:'')+' '+esc(i?i.name:'Insumo');}).join(' · ')+'</strong><small>'+date(m.occurred_at)+' · '+esc(src?src.name:'Origen externo')+(dst?' → '+esc(dst.name):'')+(m.patient_id?' · '+esc(patientName(m.patient_id)):'')+'</small><p>'+esc(m.reason)+'</p></div>'+(state.canManage&&!reversed&&m.movement_type!=='reversal'?'<button data-reverse="'+m.id+'">Corregir</button>':'')+'</article>';}).join(''):'<div class="inventory-empty"><strong>Aún no hay movimientos</strong><p>Las recepciones, consumos, traslados y mermas aparecerán aquí.</p></div>';h.querySelectorAll('[data-reverse]').forEach(function(b){b.onclick=function(){reverseMovement(b.dataset.reverse);};});}
  function orderStatus(s){return {ordered:'Por recibir',partially_received:'Recepción parcial',received:'Recibido',cancelled:'Cancelado'}[s]||s;}
  function renderOrders(){var h=document.getElementById('inventory-orders');h.innerHTML=state.orders.length?state.orders.map(function(o){var sup=by(state.suppliers,o.supplier_id),loc=by(state.locations,o.destination_location_id),lines=state.orderLines.filter(function(l){return l.purchase_order_id===o.id;}),total=lines.reduce(function(a,l){return a+Number(l.ordered_quantity)*Number(l.unit_cost||0);},0),ordered=lines.reduce(function(a,l){return a+Number(l.ordered_quantity||0);},0),received=lines.reduce(function(a,l){return a+Number(l.received_quantity||0);},0),progress=ordered?Math.min(100,Math.round(received/ordered*100)):0,open=o.status==='ordered'||o.status==='partially_received';return '<article class="inventory-order"><div class="inventory-order-main"><span class="inventory-badge" data-status="'+o.status+'">'+orderStatus(o.status)+'</span><h3>'+esc(o.reference||'Pedido '+o.id.slice(0,8))+'</h3><p>'+esc(sup?sup.name:'Proveedor')+' · '+esc(loc?loc.name:'Destino')+'</p><small>'+lines.length+' insumos · '+money(total)+(o.expected_on?' · Esperado '+date(o.expected_on):'')+'</small><div class="inventory-order-progress"><div><span style="width:'+progress+'%"></span></div><small>'+fmt(received)+' de '+fmt(ordered)+' unidades recibidas · '+progress+'%</small></div></div><div>'+(state.canManage&&open?'<button class="btn btn-primary" data-receive="'+o.id+'">Recibir</button>':'')+(state.canManage&&o.status==='ordered'?'<button data-cancel-order="'+o.id+'">Cancelar</button>':'')+'</div></article>';}).join(''):'<div class="inventory-empty"><strong>No hay pedidos</strong><p>Crea una orden para registrar la compra antes de recibir lotes.</p></div>';h.querySelectorAll('[data-receive]').forEach(function(b){b.onclick=function(){openReceive(by(state.orders,b.dataset.receive));};});h.querySelectorAll('[data-cancel-order]').forEach(function(b){b.onclick=function(){cancelOrder(by(state.orders,b.dataset.cancelOrder));};});}
