    state.orderLines.forEach(function(line){var quantity=Number(line.received_quantity||0),cost=line.unit_cost==null?null:Number(line.unit_cost);if(quantity<=0||cost==null)return;var entry=totals[line.item_id]||(totals[line.item_id]={quantity:0,value:0});entry.quantity+=quantity;entry.value+=quantity*cost;});
    return Object.keys(totals).reduce(function(index,itemId){var entry=totals[itemId];index[itemId]=entry.quantity?entry.value/entry.quantity:null;return index;},{});
