  function renderCatalog(){var items=document.getElementById('inventory-items'),sup=document.getElementById('inventory-suppliers'),loc=document.getElementById('inventory-locations');items.innerHTML=state.items.filter(function(x){return x.active;}).map(function(x){var flags=[x.track_lot?'Lote':'',x.track_expiry?'Caducidad':'',x.track_serial?'Serie':'',x.requires_patient_trace?'Paciente':''].filter(Boolean);return '<article><div><strong>'+esc(x.name)+'</strong><small>'+esc(x.sku)+' · '+esc(x.category)+' · '+esc(x.unit)+'</small></div><span>'+esc(flags.join(' · ')||'Control simple')+'</span></article>';}).join('')||'<div class="inventory-empty">Agrega el primer insumo dental.</div>';sup.innerHTML=state.suppliers.filter(function(x){return x.active;}).map(function(x){return '<article><div><strong>'+esc(x.name)+'</strong><small>'+esc(x.contact_name||x.email||x.phone||'Sin contacto')+'</small></div></article>';}).join('')||'<div class="inventory-empty">Agrega un proveedor.</div>';loc.innerHTML=state.locations.filter(function(x){return x.active;}).map(function(x){var b=by(state.branches,x.branch_id);return '<article><div><strong>'+esc(x.name)+'</strong><small>'+esc(b?b.name:'Sucursal')+' · '+esc(x.location_type)+'</small></div></article>';}).join('')||'<div class="inventory-empty">Configura una ubicación.</div>';renderKits();}
  function render(){renderInventoryFocus();renderMetrics();renderStock();renderMovements();renderOrders();renderCatalog();renderCosts();document.querySelectorAll('[data-inventory-tab]').forEach(function(b){b.setAttribute('aria-selected',String(b.dataset.inventoryTab===state.tab));});document.querySelectorAll('[data-inventory-panel]').forEach(function(p){p.hidden=p.dataset.inventoryPanel!==state.tab;});['inventory-new-movement','inventory-new-order','inventory-add-item','inventory-add-supplier','inventory-add-location','inventory-add-kit'].forEach(function(id){var x=document.getElementById(id);if(x)x.hidden=!state.canManage;});}
  async function load(force){
    if(!window.tenantId||state.loading||(state.loaded&&state.tenant===window.tenantId&&!force))return;
    state.loading=true;state.tenant=window.tenantId;notify('Cargando inventario protegido…');
    try{
      var a=await window.sb.auth.getUser();state.actor=a.data&&a.data.user&&a.data.user.id;
      var access=await Promise.all([q(window.sb.from('smyl_role_permissions').select('role_id,permission_key').eq('tenant_id',state.tenant)),q(window.sb.from('smyl_member_roles').select('user_id,role_id').eq('tenant_id',state.tenant))]);
      state.rolePermissions=access[0]||[];state.memberRoles=access[1]||[];capabilities();
      if(!state.canRead){document.getElementById('p-inventario').innerHTML='<div class="inventory-restricted"><strong>Inventario restringido</strong><p>Solicita el permiso de inventario para consultar existencias y compras.</p></div>';return;}
      var rows=await Promise.all([
        q(window.sb.from('smyl_branches').select('id,name,active').eq('tenant_id',state.tenant).eq('active',true)),
        q(window.sb.from('smyl_rooms').select('id,branch_id,name,active').eq('tenant_id',state.tenant).eq('active',true)),
        q(window.sb.from('smyl_inventory_locations').select('*').eq('tenant_id',state.tenant).eq('active',true).order('name')),
        q(window.sb.from('smyl_inventory_items').select('*').eq('tenant_id',state.tenant).order('name')),
        q(window.sb.from('smyl_inventory_suppliers').select('*').eq('tenant_id',state.tenant).order('name')),
        q(window.sb.from('smyl_inventory_reorder_levels').select('*').eq('tenant_id',state.tenant)),
        q(window.sb.from('smyl_purchase_orders').select('*').eq('tenant_id',state.tenant).order('ordered_at',{ascending:false}).limit(100)),
        Promise.resolve([]),
        q(window.sb.from('smyl_inventory_movements').select('*').eq('tenant_id',state.tenant).order('occurred_at',{ascending:false}).limit(100)),
        Promise.resolve([]),
        q(window.sb.from('camila_pacientes').select('id,nombre,apellido').eq('tenant_id',state.tenant).order('nombre')),
        q(window.sb.from('smyl_appointments').select('id,patient_id,professional_id,service_id,starts_at,status').eq('tenant_id',state.tenant).in('status',['in_progress','completed']).order('starts_at',{ascending:false}).limit(100)),
        q(window.sb.from('smyl_professionals').select('id,display_name').eq('tenant_id',state.tenant).eq('active',true)),
        q(window.sb.from('smyl_services').select('id,name,active,reference_price').eq('tenant_id',state.tenant).order('name')),
        q(window.sb.from('smyl_service_materials').select('service_id,item_id,expected_quantity').eq('tenant_id',state.tenant)),
        rpc('smyl_inventory_snapshot',{p_location_id:null}),
        rpc('smyl_inventory_lot_stock',{p_location_id:null})
      ]);
      ['branches','rooms','locations','items','suppliers','reorders','orders','orderLines','movements','movementLines','patients','appointments','professionals','services','serviceMaterials','snapshot','lots'].forEach(function(k,i){state[k]=rows[i]||[];});
      var details=await Promise.all([state.orders.length?q(window.sb.from('smyl_purchase_order_lines').select('*').eq('tenant_id',state.tenant).in('purchase_order_id',state.orders.map(function(x){return x.id;}))):Promise.resolve([]),state.movements.length?q(window.sb.from('smyl_inventory_movement_lines').select('*').eq('tenant_id',state.tenant).in('movement_id',state.movements.map(function(x){return x.id;}))):Promise.resolve([])]);
      state.orderLines=details[0]||[];state.movementLines=details[1]||[];
      if(!state.location&&state.locations[0])state.location=state.locations[0].id;
      state.loaded=true;render();notify('Existencias calculadas desde movimientos confirmados.','success');
    }catch(e){notify('No se pudo cargar inventario: '+error(e),'error');}finally{state.loading=false;}
  }
  async function reload(message){state.loaded=false;await load(true);if(message)notify(message,'success');}
  function openItem(){var d=dialog('<form><h2>Nuevo insumo dental</h2><p>Define desde el inicio la trazabilidad que este material necesita.</p><div class="inventory-form-grid"><label>SKU<input name="sku" maxlength="60" required placeholder="RES-COMP-A2"></label><label>Nombre<input name="name" maxlength="160" required placeholder="Resina compuesta A2"></label><label>Categoría<select name="category"><option>material</option><option>medicamento</option><option>implante</option><option>instrumental</option><option>esterilización</option><option>oficina</option></select></label><label>Unidad<input name="unit" maxlength="30" value="pieza" required></label><label class="check"><input type="checkbox" name="lot" checked> Controlar por lote</label><label class="check"><input type="checkbox" name="expiry"> Controlar caducidad</label><label class="check"><input type="checkbox" name="serial"> Número de serie</label><label class="check"><input type="checkbox" name="patient"> Trazabilidad por paciente</label></div><div class="inventory-actions"><button type="button" class="btn btn-secondary" data-close>Cancelar</button><button class="btn btn-primary">Guardar insumo</button></div></form>');d.querySelector('form').onsubmit=async function(e){e.preventDefault();var f=new FormData(e.currentTarget),lot=f.has('lot')||f.has('expiry')||f.has('serial')||f.has('patient');try{await q(window.sb.from('smyl_inventory_items').insert({tenant_id:state.tenant,sku:f.get('sku').trim(),name:f.get('name').trim(),category:f.get('category'),unit:f.get('unit').trim(),track_lot:lot,track_expiry:f.has('expiry'),track_serial:f.has('serial'),requires_patient_trace:f.has('patient'),created_by:state.actor}));close();await reload('Insumo agregado al catálogo.');}catch(err){notify(error(err),'error');}};}
