  function openReorder(itemId,locationId){var item=by(state.items,itemId),row=state.reorders.find(function(x){return x.item_id===itemId&&x.location_id===locationId;});var d=dialog('<form><h2>Mínimos · '+esc(item.name)+'</h2><div class="inventory-form-grid"><label>Mínimo<input name="minimum" type="number" min="0" step="0.001" value="'+Number(row&&row.minimum_quantity||0)+'" required></label><label>Objetivo de reposición<input name="target" type="number" min="0" step="0.001" value="'+Number(row&&row.target_quantity||0)+'" required></label></div><div class="inventory-actions"><button type="button" class="btn btn-secondary" data-close>Cancelar</button><button class="btn btn-primary">Guardar niveles</button></div></form>');d.querySelector('form').onsubmit=async function(e){e.preventDefault();var f=new FormData(e.currentTarget),min=Number(f.get('minimum')),target=Number(f.get('target'));if(target<min){notify('El objetivo no puede ser menor al mínimo.','error');return;}try{await q(window.sb.from('smyl_inventory_reorder_levels').upsert({tenant_id:state.tenant,location_id:locationId,item_id:itemId,minimum_quantity:min,target_quantity:target,updated_by:state.actor,updated_at:new Date().toISOString()}));close();await reload('Niveles de reposición actualizados.');}catch(err){notify(error(err),'error');}};}
